const rawInputs = $input.all();
const unifiedItems = [];
const nowIso = new Date().toISOString();

const myCoreSkills = [
  "python", "fastapi", "next.js", "nextjs", "react", "typescript",
  "javascript", "supabase", "postgres", "postgresql", "sql",
  "docker", "n8n", "automation", "webhook", "api", "rest",
  "backend", "full stack", "fullstack", "linux",
  "artificial intelligence", "machine learning", "llm", "agent", "agents"
];

function findMatchedSkills(text) {
  const normalized = String(text || "").toLowerCase();

  return myCoreSkills.filter(skill => {
    if (skill.includes(" ")) return normalized.includes(skill);

    const escaped = skill.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return new RegExp(
      `(^|[^a-z0-9+#.])${escaped}($|[^a-z0-9+#.])`,
      "i"
    ).test(normalized);
  });
}

function clampScore(score) {
  return Math.max(0, Math.min(100, Math.round(score)));
}

function safeDate(value) {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function makeItem(fields) {
  return {
    json: {
      ...fields,
      collected_at: nowIso
    }
  };
}

// =====================================================
// CASE 1: GitHub Search Issues API response
// =====================================================
for (const item of rawInputs) {
  const data = item.json || {};

  if (
    Array.isArray(data.items) &&
    typeof data.total_count === "number"
  ) {
    for (const issue of data.items) {
      if (
        !issue ||
        issue.pull_request ||
        issue.state === "closed" ||
        !issue.html_url
      ) continue;

      const title = issue.title || "Untitled GitHub issue";

      const repo = issue.repository_url
        ? issue.repository_url.replace(
            "https://api.github.com/repos/", ""
          )
        : "Unknown repository";

      const labels = Array.isArray(issue.labels)
        ? issue.labels.map(label =>
            typeof label === "string" ? label : label?.name
          ).filter(Boolean)
        : [];

      const searchBlob =
        `${title} ${repo} ${labels.join(" ")} ${issue.body || ""}`;

      const matchedSkills = findMatchedSkills(searchBlob);

      // A dollar amount is not proof of a cash bounty.
      const bountyEvidence =
        labels.some(label =>
          /bounty|algora|polar|funded|cash reward/i.test(label)
        ) ||
        /algora|polar\.sh|bounty/i.test(searchBlob);

      const dollarMatch = searchBlob.match(
        /(?:US\$|\$)\s?\d+(?:,\d{3})*(?:\.\d{1,2})?/
      );

      let score = 25;

      if (bountyEvidence) score += 25;
      if (bountyEvidence && dollarMatch) score += 15;

      score += Math.min(25, matchedSkills.length * 5);

      if ((issue.comments ?? 0) <= 3) score += 5;

      const verificationStatus = bountyEvidence
        ? "Potential bounty — verify original terms and active status"
        : dollarMatch
          ? "Unverified monetary mention — bounty not confirmed"
          : "Open issue — bounty not established";

      const compensation =
        bountyEvidence && dollarMatch
          ? `${dollarMatch[0]} mentioned; amount and active status unverified`
          : "Not verified";

      unifiedItems.push(makeItem({
        uid: `gh_${issue.id ?? issue.node_id ?? issue.html_url}`,
        module: "EARNING_OPPORTUNITY",
        source_type: "GitHub Issue Candidate",
        title,
        organization: repo,
        url: issue.html_url,

        // Creation date and update date are separate.
        published_at: safeDate(issue.created_at),
        updated_at: safeDate(issue.updated_at),

        india_eligibility:
          "Unknown — verify reward terms, platform eligibility and payment rules",

        compensation,
        verification_status: verificationStatus,
        matched_skills: matchedSkills,

        relevance_score: clampScore(score),

        score_explanation:
          `Base 25; bounty indicators ${bountyEvidence ? "+25" : "+0"}; ` +
          `amount with bounty indicators ${bountyEvidence && dollarMatch ? "+15" : "+0"}; ` +
          `skill overlap +${Math.min(25, matchedSkills.length * 5)}; ` +
          `low comment count ${(issue.comments ?? 0) <= 3 ? "+5" : "+0"}. ` +
          "Triage score, not probability of payment.",

        where_to_go: issue.html_url,

        how_to_capture:
          "Open the original issue. Verify the active reward, its terms, " +
          "contribution instructions and eligibility before investing time."
      }));
    }

    continue;
  }

  // =====================================================
  // CASE 2: RemoteOK individual job object
  // =====================================================
  if (data.slug || data.position || data.legal) {
    // Skip legal/notice records and incomplete jobs.
    if (!data.id || !data.position) continue;

    const title = String(data.position);
    const company = data.company || "Company not specified";

    const url =
      data.apply_url ||
      data.url ||
      (data.slug
        ? `https://remoteok.com/remote-jobs/${data.slug}`
        : null);

    if (!url) continue;

    const tags = Array.isArray(data.tags)
      ? data.tags.join(" ")
      : "";

    const location = String(data.location || "Not specified");

    const searchBlob =
      `${title} ${company} ${tags} ${data.description || ""}`;

    const matchedSkills = findMatchedSkills(searchBlob);

    // Only keep roles with a matching skill.
    if (matchedSkills.length === 0) continue;

    // Exclude clearly stated restrictions; do not assume
    // all other jobs accept applicants from India.
    const explicitlyRestricted =
      /\b(us only|united states only|usa only|uk only|united kingdom only|canada only)\b/i
        .test(location);

    if (explicitlyRestricted) continue;

    const salaryMin =
      data.salary_min != null && data.salary_min !== ""
        ? Number(data.salary_min)
        : null;

    const salaryMax =
      data.salary_max != null && data.salary_max !== ""
        ? Number(data.salary_max)
        : null;

    const validMin =
      salaryMin !== null &&
      Number.isFinite(salaryMin) &&
      salaryMin > 0;

    const validMax =
      salaryMax !== null &&
      Number.isFinite(salaryMax) &&
      salaryMax > 0;

    const currency = data.salary_currency || "Currency unspecified";

    let compensation = "Not disclosed in feed";

    if (validMin && validMax) {
      compensation =
        `${currency} ${salaryMin}–${salaryMax}; ` +
        "period and terms require verification";
    } else if (validMin) {
      compensation =
        `${currency} ${salaryMin} minimum reported; verify details`;
    } else if (validMax) {
      compensation =
        `${currency} ${salaryMax} maximum reported; verify details`;
    }

    const broadLocation =
      /\b(worldwide|global|india|anywhere)\b/i.test(location);

    let score = 35 + Math.min(40, matchedSkills.length * 8);

    if (broadLocation) score += 10;
    if (safeDate(data.date)) score += 5;

    unifiedItems.push(makeItem({
      uid: `rok_${data.id}`,
      module: "EARNING_OPPORTUNITY",
      source_type: "RemoteOK Tech Role",
      title: `${title} @ ${company}`,
      organization: company,
      url,

      published_at: safeDate(data.date),
      updated_at: null,

      india_eligibility: broadLocation
        ? `Feed location says "${location}"; confirm eligibility on the listing`
        : `Unknown — feed location is "${location}"`,

      compensation,

      verification_status:
        validMin || validMax
          ? "Source-reported salary — verify currency, period and current listing"
          : "Compensation not disclosed in feed",

      matched_skills: matchedSkills,
      relevance_score: clampScore(score),

      score_explanation:
        `Skill overlap +${Math.min(40, matchedSkills.length * 8)}; ` +
        `broad-location indicator ${broadLocation ? "+10" : "+0"}; ` +
        `valid listing date ${safeDate(data.date) ? "+5" : "+0"}. ` +
        "Triage score, not probability of hiring.",

      where_to_go: url,

      how_to_capture:
        "Verify that the role is active, accepts applicants from India, " +
        "matches your experience, and has clear application and compensation terms."
    }));

    continue;
  }

  // =====================================================
  // CASE 3: Hacker News Algolia response
  // =====================================================
  if (Array.isArray(data.hits)) {
    for (const hit of data.hits) {
      if (!hit || !hit.objectID) continue;

      const title =
        hit.title || hit.story_title || "Untitled Hacker News item";

      const discussionUrl =
        `https://news.ycombinator.com/item?id=${hit.objectID}`;

      const url = hit.url || discussionUrl;

      const matchedSkills = findMatchedSkills(
        `${title} ${hit.story_text || ""} ${hit.url || ""}`
      );

      let score = 40 + Math.min(40, matchedSkills.length * 8);

      if ((hit.points || 0) > 10) score += 5;
      if ((hit.num_comments || 0) > 5) score += 5;

      unifiedItems.push(makeItem({
        uid: `hn_${hit.objectID}`,
        module: "AI_LEARNING_RADAR",
        source_type: "Hacker News Technical Signal",
        title,
        organization: `HN author: ${hit.author || "unknown"}`,
        url,
        discussion_url: discussionUrl,

        published_at: safeDate(hit.created_at),
        updated_at: null,

        india_eligibility: "Not applicable — learning/technology signal",
        compensation: "No earning claim",

        verification_status:
          "Community signal — inspect original source; engagement does not prove correctness",

        //matched_skills,
        //relevance_score: clampScore(score),
        matched_skills: matchedSkills,
        relevance_score: clampScore(score),

        score_explanation:
          `Skill overlap +${Math.min(40, matchedSkills.length * 8)}; ` +
          `community engagement +${((hit.points || 0) > 10 ? 5 : 0) + ((hit.num_comments || 0) > 5 ? 5 : 0)}. ` +
          "Triage score, not factual reliability.",

        where_to_go: url,

        how_to_capture:
          "Read the original source, inspect the discussion for context, " +
          "and decide whether the information has practical value for your learning."
      }));
    }
  }
}

// =====================================================
// Deduplicate within this execution and sort.
// Persistent cross-run deduplication requires storage.
// =====================================================
const deduped = new Map();

for (const item of unifiedItems) {
  const key = item.json.uid || item.json.url;
  const existing = deduped.get(key);

  if (
    !existing ||
    item.json.relevance_score > existing.json.relevance_score
  ) {
    deduped.set(key, item);
  }
}

return [...deduped.values()].sort(
  (a, b) => b.json.relevance_score - a.json.relevance_score
);

// Stage 5 & 6 (v2): Cross-Run State, URL Deduplication, Diversity Cap & HTML Digest Builder
const allItems = $input.all().map(i => i.json);
const nowIso = new Date().toISOString();

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUids) {
  staticData.seenUids = {};
}

// Normalize URLs so "https://www.nativeship.io/" and "https://www.nativeship.io" match
function normalizeUrl(u) {
  return String(u || "").trim().toLowerCase().replace(/\/+$/, "");
}

// Reject executive/management titles or non-India regions that slipped through
const excludedTitlePattern = /\b(head of|vp of|vice president|director of|principal|chief|c-level|staff manager|account manager)\b/i;
const excludedLocationPattern = /\b(brazil|latam|latin america|mexico|argentina|colombia|europe only|eu only|emea only|kansas|california|texas|new york|florida|washington|illinois|massachusetts|north america only)\b/i;

const MIN_SCORE = 45;
const MAX_PER_ORG = 2;
const MAX_OPPORTUNITIES = 10;
const MAX_LEARNING = 6;

const orgCounts = {};
const seenUrlsThisRun = new Set();
const freshOpportunities = [];
const freshLearning = [];
let skippedDuplicatesCount = 0;
let skippedOrgCapCount = 0;
let skippedRoleOrRegionCount = 0;

for (const item of allItems) {
  if (!item || !item.uid || !item.url) continue;

  const normUrl = normalizeUrl(item.url);

  // 1. Deduplicate by UID (cross-run) and by normalized URL (within-run & cross-run)
  if (
    staticData.seenUids[item.uid] ||
    staticData.seenUids[normUrl] ||
    seenUrlsThisRun.has(normUrl)
  ) {
    skippedDuplicatesCount++;
    continue;
  }

  // 2. Filter out executive titles & region-locked locations for Earning Opportunities
  if (item.module === "EARNING_OPPORTUNITY") {
    if (
      excludedTitlePattern.test(item.title || "") ||
      excludedLocationPattern.test(item.india_eligibility || "")
    ) {
      skippedRoleOrRegionCount++;
      continue;
    }
  }

  // 3. Minimum relevance threshold
  if ((item.relevance_score || 0) < MIN_SCORE) continue;

  // 4. Enforce diversity cap (max 2 items per repo/company per digest)
  const orgKey = (item.organization || "unknown").toLowerCase();
  if (item.module === "EARNING_OPPORTUNITY") {
    orgCounts[orgKey] = (orgCounts[orgKey] || 0) + 1;
    if (orgCounts[orgKey] > MAX_PER_ORG) {
      skippedOrgCapCount++;
      continue;
    }
  }

  if (item.module === "EARNING_OPPORTUNITY" && freshOpportunities.length < MAX_OPPORTUNITIES) {
    freshOpportunities.push(item);
    seenUrlsThisRun.add(normUrl);
    staticData.seenUids[item.uid] = nowIso;
    staticData.seenUids[normUrl] = nowIso;
  } else if (item.module === "AI_LEARNING_RADAR" && freshLearning.length < MAX_LEARNING) {
    freshLearning.push(item);
    seenUrlsThisRun.add(normUrl);
    staticData.seenUids[item.uid] = nowIso;
    staticData.seenUids[normUrl] = nowIso;
  }
}

// Cap staticData history to 1000 keys
const uidKeys = Object.keys(staticData.seenUids);
if (uidKeys.length > 1000) {
  for (const oldKey of uidKeys.slice(0, uidKeys.length - 1000)) {
    delete staticData.seenUids[oldKey];
  }
}

function esc(str) {
  return String(str || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const dateLabel = new Date().toLocaleDateString("en-IN", {
  weekday: "short", year: "numeric", month: "short", day: "numeric"
});

let html = `
<div style="font-family: Arial, sans-serif; max-width: 720px; margin: 0 auto; color: #1f2937; line-height: 1.5;">
  <h2 style="color: #111827; border-bottom: 2px solid #2563eb; padding-bottom: 8px;">
    🎯 AI Opportunity &amp; Learning Radar — ${esc(dateLabel)}
  </h2>
  <p style="font-size: 13px; color: #4b5563;">
    <strong>Pipeline Summary:</strong> Evaluated ${allItems.length} items | 
    Selected <strong>${freshOpportunities.length}</strong> actionable opportunities &amp; <strong>${freshLearning.length}</strong> learning signals | 
    Filtered ${skippedOrgCapCount} same-org, ${skippedDuplicatesCount} duplicate URLs/UIDs, ${skippedRoleOrRegionCount} region/exec mismatches.
  </p>

  <h3 style="background: #eff6ff; color: #1d4ed8; padding: 8px 12px; border-left: 4px solid #2563eb;">
    💰 Module A: Top Matching Earning Opportunities (${freshOpportunities.length})
  </h3>
`;

if (freshOpportunities.length === 0) {
  html += `<p><em>No new high-confidence earning opportunities matched your threshold in this run.</em></p>`;
} else {
  for (const opp of freshOpportunities) {
    const skillsList = Array.isArray(opp.matched_skills) ? opp.matched_skills.join(", ") : opp.matched_skills;
    html += `
    <div style="border: 1px solid #e5e7eb; border-radius: 6px; padding: 12px; margin-bottom: 14px; background: #ffffff;">
      <div style="font-size: 12px; color: #6b7280; margin-bottom: 4px;">
        <strong>[${esc(opp.source_type)}]</strong> • Org: <strong>${esc(opp.organization)}</strong> • Triage Score: <strong>${esc(opp.relevance_score)}/100</strong>
      </div>
      <div style="font-size: 16px; font-weight: bold; margin-bottom: 6px;">
        <a href="${esc(opp.url)}" style="color: #2563eb; text-decoration: none;">${esc(opp.title)}</a>
      </div>
      <div style="font-size: 13px; margin-bottom: 4px;">
        <strong>💵 Compensation:</strong> ${esc(opp.compensation)} <em>(${esc(opp.verification_status)})</em>
      </div>
      <div style="font-size: 13px; margin-bottom: 4px;">
        <strong>🇮🇳 India Eligibility:</strong> ${esc(opp.india_eligibility)}
      </div>
      <div style="font-size: 13px; margin-bottom: 6px;">
        <strong>🛠️ Matched Skills:</strong> ${esc(skillsList || "General Tech")}
      </div>
      <div style="background: #f9fafb; border-left: 3px solid #10b981; padding: 8px; font-size: 13px;">
        <strong>🚀 How to Capture This:</strong> ${esc(opp.how_to_capture)}<br/>
        <strong>🔗 Direct Link:</strong> <a href="${esc(opp.where_to_go)}">${esc(opp.where_to_go)}</a>
      </div>
    </div>`;
  }
}

html += `
  <h3 style="background: #f0fdf4; color: #15803d; padding: 8px 12px; border-left: 4px solid #16a34a; margin-top: 24px;">
    🧠 Module B: AI &amp; Automation Learning Radar (${freshLearning.length})
  </h3>
`;

if (freshLearning.length === 0) {
  html += `<p><em>No new learning signals matched your threshold in this run.</em></p>`;
} else {
  for (const sig of freshLearning) {
    const skillsList = Array.isArray(sig.matched_skills) ? sig.matched_skills.join(", ") : sig.matched_skills;
    html += `
    <div style="border: 1px solid #e5e7eb; border-radius: 6px; padding: 10px; margin-bottom: 10px;">
      <div style="font-size: 15px; font-weight: bold;">
        <a href="${esc(sig.url)}" style="color: #15803d; text-decoration: none;">${esc(sig.title)}</a>
      </div>
      <div style="font-size: 12px; color: #4b5563; margin-top: 4px;">
        <strong>Matched Stack:</strong> ${esc(skillsList || "n8n / AI")} | <strong>Score:</strong> ${esc(sig.relevance_score)}/100<br/>
        <strong>Action:</strong> ${esc(sig.how_to_capture)}
      </div>
    </div>`;
  }
}

html += `
  <hr style="border: none; border-top: 1px solid #e5e7eb; margin-top: 20px;"/>
  <p style="font-size: 11px; color: #9ca3af;">
    Generated locally by n8n AI Opportunity &amp; Learning Radar (₹0 Cost Architecture). All compensation and eligibility claims are source-reported and must be verified on the destination page before investing work.
  </p>
</div>
`;

return [{
  json: {
    subject: `🎯 Opportunity Radar (${dateLabel}): ${freshOpportunities.length} Matched Gigs & Bounties`,
    should_send_email: (freshOpportunities.length + freshLearning.length) > 0,
    total_evaluated: allItems.length,
    opportunities_selected: freshOpportunities.length,
    learning_selected: freshLearning.length,
    skipped_same_org: skippedOrgCapCount,
    skipped_duplicates: skippedDuplicatesCount,
    skipped_role_or_region: skippedRoleOrRegionCount,
    opportunities: freshOpportunities,
    learning_signals: freshLearning,
    html_report: html,
    generated_at: nowIso
  }
}];
